import { constants } from "node:fs";
import {
  lstat,
  mkdir,
  open,
  type FileHandle,
  unlink,
} from "node:fs/promises";
import { basename, dirname, parse, resolve, sep } from "node:path";
import type { Plugin, ResolvedConfig, ViteDevServer } from "vite";

import {
  isViteClientCarrier,
  readJsonBody,
  requestPathname,
  sendJson,
  writeMalformedBodyResponse,
} from "./http";

const DEFAULT_ENDPOINT = "/__vibe/error-collector";
const DEFAULT_OUTPUT_FILE = "/tmp/vibe/runtime-errors.log";
const DEFAULT_MAX_BODY_BYTES = 64 * 1_024;
const DEFAULT_MAX_OUTPUT_BYTES = 1 * 1_024 * 1_024;
const DEFAULT_BODY_READ_TIMEOUT_MS = 2_000;
const MIN_MAX_OUTPUT_BYTES = 128;
const COLLECTOR_INSTALL_FLAG = "__vibeErrorCollectorInstalled";
const COLLECTOR_DEDUP_WINDOW_MS = 5_000;
const COLLECTOR_DEDUP_MAX_ENTRIES = 128;
const CONTROL_ENDPOINTS = new Set([
  "/__vibe/restart-announce",
  "/_sandbox/preview/viewers",
  "/_sandbox/preview/execute",
]);
const pathQueues = new Map<string, Promise<void>>();

export interface ErrorCollectorOptions {
  /** Browser-facing report endpoint. */
  endpoint?: string;
  /** JSONL output path. Relative paths resolve from Vite's root. */
  outputFile?: string;
  /** Maximum accepted HTTP request body size. */
  maxBodyBytes?: number;
  /** Maximum active and rotated log size. */
  maxOutputBytes?: number;
  /** Maximum time to wait for a complete browser report body. */
  bodyReadTimeoutMs?: number;
  /** Clear the active log when the dev server starts. */
  resetOnStart?: boolean;
}

type ErrorCollectorHooks = {
  configResolved: (config: ResolvedConfig) => void;
  configureServer: (server: ViteDevServer) => () => Promise<void>;
  transform: (
    code: string,
    id: string,
    options?: { ssr?: boolean },
  ) => { code: string; map: null } | null;
  transformIndexHtml: () => Array<{
    tag: "script";
    children: string;
    injectTo: "head-prepend";
  }>;
  close: () => Promise<void>;
};

type HttpServer = NonNullable<ViteDevServer["httpServer"]>;
type HttpClosePatch = {
  callbacks: Set<() => void>;
  originalClose: HttpServer["close"];
  wrapper: HttpServer["close"];
};
const httpClosePatches = new WeakMap<HttpServer, HttpClosePatch>();

export function attachHttpServerClose(
  server: HttpServer,
  callback: () => void,
): () => void {
  let patch = httpClosePatches.get(server);
  if (!patch) {
    const callbacks = new Set<() => void>();
    const originalClose = server.close;
    const wrapper: HttpServer["close"] = function (...args: unknown[]) {
      for (const close of [...callbacks]) close();
      return (originalClose as (...values: unknown[]) => unknown).apply(
        server,
        args,
      ) as ReturnType<HttpServer["close"]>;
    } as HttpServer["close"];
    patch = { callbacks, originalClose, wrapper };
    httpClosePatches.set(server, patch);
    server.close = wrapper;
  }
  patch.callbacks.add(callback);
  server.once("close", callback);
  let detached = false;
  return () => {
    if (detached) return;
    detached = true;
    server.off("close", callback);
    patch?.callbacks.delete(callback);
    if (patch?.callbacks.size === 0) {
      if (server.close === patch.wrapper) server.close = patch.originalClose;
      httpClosePatches.delete(server);
    }
  };
}

function normalizeEndpoint(endpoint: string): string {
  if (
    !endpoint.startsWith("/") ||
    endpoint.startsWith("//") ||
    endpoint.includes("?") ||
    endpoint.includes("#")
  ) {
    throw new Error(
      `errorCollectorPlugin endpoint must be a root-relative path, received ${JSON.stringify(endpoint)}`,
    );
  }
  const normalizedEndpoint = new URL(endpoint, "http://collector.invalid")
    .pathname;
  if (!normalizedEndpoint.startsWith("/") || normalizedEndpoint.startsWith("//")) {
    throw new Error(
      `errorCollectorPlugin endpoint must normalize to a root-relative path, received ${JSON.stringify(endpoint)}`,
    );
  }
  if (CONTROL_ENDPOINTS.has(normalizedEndpoint)) {
    throw new Error(
      `errorCollectorPlugin endpoint collides with a control path: ${endpoint}`,
    );
  }
  return normalizedEndpoint;
}

function validatePositiveSafeInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new Error(
      `errorCollectorPlugin ${name} must be a positive safe integer`,
    );
  }
}

function browserCollectorScript(endpoint: string): string {
  return `
(() => {
  if (globalThis.${COLLECTOR_INSTALL_FLAG}) return;
  globalThis.${COLLECTOR_INSTALL_FLAG} = true;
  const endpoint = ${JSON.stringify(endpoint).replaceAll("<", "\\u003c")};
  const clip = (value) => String(value ?? "").slice(0, 10000);
  const recentReports = new Map();
  const shouldPost = (report, pageUrl) => {
    const now = globalThis.Date?.now?.() ?? Date.now();
    for (const [fingerprint, timestamp] of recentReports) {
      if (now < timestamp || now - timestamp >= ${COLLECTOR_DEDUP_WINDOW_MS}) {
        recentReports.delete(fingerprint);
      }
    }
    const fingerprint = JSON.stringify([
      report.type,
      report.message,
      report.stack,
      report.filename,
      report.resourceUrl,
      pageUrl,
    ]);
    const previous = recentReports.get(fingerprint);
    if (
      previous !== undefined &&
      now >= previous &&
      now - previous < ${COLLECTOR_DEDUP_WINDOW_MS}
    ) {
      recentReports.delete(fingerprint);
      recentReports.set(fingerprint, previous);
      return false;
    }
    recentReports.set(fingerprint, now);
    if (recentReports.size > ${COLLECTOR_DEDUP_MAX_ENTRIES}) {
      recentReports.delete(recentReports.keys().next().value);
    }
    return true;
  };
  const describe = (value, fallback) => {
    if (value && typeof value === "object") {
      const message = "message" in value ? clip(value.message) : "";
      const stack = "stack" in value ? clip(value.stack) : "";
      const name = "name" in value ? clip(value.name) : "";
      if (message || stack || name) {
        return {
          name: name || undefined,
          message: message || fallback,
          stack: stack || undefined,
        };
      }
      try {
        const seen = new WeakSet();
        const json = JSON.stringify(value, (_key, nested) => {
          if (typeof nested === "bigint") return String(nested);
          if (nested && typeof nested === "object") {
            if (seen.has(nested)) return "[Circular]";
            seen.add(nested);
          }
          return nested;
        });
        if (json) return { message: clip(json) };
      } catch {}
    }
    return { message: value == null ? fallback : clip(value) };
  };
  const post = (report) => {
    try {
      const pageUrl = clip(globalThis.location?.href) || undefined;
      if (!shouldPost(report, pageUrl)) return;
      const body = JSON.stringify({
        ...report,
        timestamp: new Date().toISOString(),
        pageUrl,
        userAgent: globalThis.navigator?.userAgent,
      });
      void globalThis.fetch(endpoint, {
        method: "POST",
        headers: {
          "content-type": "application/json",
        },
        body,
        keepalive: true,
      }).catch(() => {});
    } catch {}
  };
  globalThis.addEventListener("error", (event) => {
    const target = event.target;
    if (
      target &&
      target !== globalThis &&
      typeof target === "object" &&
      "tagName" in target
    ) {
      const tagName = clip(target.tagName).toLowerCase();
      const resourceUrl = clip(
        target.currentSrc || target.src || target.href || "",
      );
      post({
        type: "resource-error",
        message: resourceUrl
          ? \`Failed to load <\${tagName}>: \${resourceUrl}\`
          : \`Failed to load <\${tagName}>\`,
        tagName,
        resourceUrl: resourceUrl || undefined,
      });
      return;
    }
    post({
      type: "runtime-error",
      ...describe(event.error || event.message, "Unknown runtime error"),
      filename: clip(event.filename) || undefined,
      line: Number.isFinite(event.lineno) ? event.lineno : undefined,
      column: Number.isFinite(event.colno) ? event.colno : undefined,
    });
  }, true);
  globalThis.addEventListener("unhandledrejection", (event) => {
    post({
      type: "unhandled-rejection",
      ...describe(event.reason, "Unhandled promise rejection"),
    });
  }, true);
})();
`;
}

function queueForPath(path: string, operation: () => Promise<void>): Promise<void> {
  const previous = pathQueues.get(path) ?? Promise.resolve();
  const current = previous.catch(() => {}).then(operation);
  pathQueues.set(path, current);
  void current.then(
    () => {
      if (pathQueues.get(path) === current) pathQueues.delete(path);
    },
    () => {
      if (pathQueues.get(path) === current) pathQueues.delete(path);
    },
  );
  return current;
}

type DirectoryAnchor = {
  dev: bigint;
  handle: FileHandle;
  ino: bigint;
  path: string;
};

type ParentAnchor = DirectoryAnchor & {
  chain: DirectoryAnchor[];
};

function directoryPrefixes(path: string): string[] {
  const root = parse(path).root;
  const relative = path.slice(root.length);
  const segments = relative.split(sep).filter(Boolean);
  const prefixes: string[] = [];
  let current = root;
  for (const segment of segments) {
    current = resolve(current, segment);
    prefixes.push(current);
  }
  return prefixes;
}

function resolveCollectorOutput(root: string, outputFile: string): string {
  const outputPath = resolve(root, outputFile);
  if (
    process.platform === "darwin" &&
    (outputPath === "/tmp" || outputPath.startsWith("/tmp/"))
  ) {
    return `/private${outputPath}`;
  }
  return outputPath;
}

async function openDirectory(path: string): Promise<FileHandle> {
  const handle = await open(
    path,
    constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW,
  );
  const info = await handle.stat({ bigint: true });
  if (!info.isDirectory()) {
    await handle.close();
    throw new Error(`Collector directory is not a regular directory: ${path}`);
  }
  return handle;
}

function isStickySystemTemp(path: string, mode: number, uid: number): boolean {
  return (
    uid === 0 &&
    (mode & 0o1000) !== 0 &&
    ["/tmp", "/private/tmp", "/var/tmp", "/private/var/tmp"].includes(path)
  );
}

function assertDarwinDirectoryBoundary(
  path: string,
  info: Awaited<ReturnType<FileHandle["stat"]>>,
): void {
  const expectedUid = process.geteuid?.();
  const mode = Number(info.mode) & 0o7777;
  const uid = Number(info.uid);
  const ownerAllowed =
    expectedUid === undefined || uid === expectedUid || uid === 0;
  const writableByOthers = (mode & 0o022) !== 0;
  if (
    !ownerAllowed ||
    (writableByOthers && !isStickySystemTemp(path, mode, uid))
  ) {
    throw new Error(`Collector directory is outside the Darwin trust boundary: ${path}`);
  }
}

async function descriptorRelativePath(
  directory: DirectoryAnchor,
  name: string,
): Promise<string | undefined> {
  if (process.platform !== "linux") return undefined;
  let probe: FileHandle | undefined;
  try {
    probe = await open(
      `/proc/self/fd/${directory.handle.fd}/.`,
      constants.O_RDONLY | constants.O_DIRECTORY,
    );
    const info = await probe.stat({ bigint: true });
    if (info.dev === directory.dev && info.ino === directory.ino) {
      return `/proc/self/fd/${directory.handle.fd}/${name}`;
    }
  } catch {
    // Linux without procfs cannot provide the required traversal guarantee.
  } finally {
    await probe?.close().catch(() => {});
  }
  return undefined;
}

async function closeDirectoryChain(chain: DirectoryAnchor[]): Promise<void> {
  await Promise.all(chain.map(({ handle }) => handle.close().catch(() => {})));
}

async function createAndAnchorParent(
  parentPath: string,
  secureExistingDefaultDirectory: boolean,
): Promise<ParentAnchor> {
  const rootPath = parse(parentPath).root;
  const rootHandle = await openDirectory(rootPath);
  const rootInfo = await rootHandle.stat({ bigint: true });
  const chain: DirectoryAnchor[] = [
    {
      dev: rootInfo.dev,
      handle: rootHandle,
      ino: rootInfo.ino,
      path: rootPath,
    },
  ];
  try {
    if (process.platform === "darwin") {
      assertDarwinDirectoryBoundary(rootPath, await rootHandle.stat());
    }
    for (const prefix of directoryPrefixes(parentPath)) {
      const parent = chain.at(-1)!;
      const name = basename(prefix);
      const descriptorPath = await descriptorRelativePath(parent, name);
      if (process.platform === "linux" && !descriptorPath) {
        throw new Error("Linux collector storage requires /proc/self/fd traversal");
      }
      const childPath = descriptorPath ?? prefix;
      let created = false;
      try {
        const info = await lstat(childPath);
        if (info.isSymbolicLink() || !info.isDirectory()) {
          throw new Error(`Collector directory has an unsafe ancestor: ${prefix}`);
        }
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        await mkdir(childPath, { mode: 0o700 });
        created = true;
      }
      const handle = await openDirectory(childPath);
      const info = await handle.stat({ bigint: true });
      const anchor: DirectoryAnchor = {
        dev: info.dev,
        handle,
        ino: info.ino,
        path: prefix,
      };
      chain.push(anchor);
      if (created) await handle.chmod(0o700);
      if (process.platform === "darwin") {
        assertDarwinDirectoryBoundary(prefix, await handle.stat());
      }
      if (prefix === parentPath && secureExistingDefaultDirectory && !created) {
        const current = await handle.stat();
        const expectedOwner = process.geteuid?.();
        if (expectedOwner !== undefined && current.uid !== expectedOwner) {
          throw new Error(
            `Default collector directory is not owned by the current user: ${prefix}`,
          );
        }
        await handle.chmod(0o700);
      }
    }
    const parent = chain.at(-1)!;
    return { ...parent, chain };
  } catch (error) {
    await closeDirectoryChain(chain);
    throw error;
  }
}

async function assertParentAnchor(anchor: ParentAnchor): Promise<void> {
  for (const directory of anchor.chain) {
    const info = await directory.handle.stat({ bigint: true });
    if (
      !info.isDirectory() ||
      info.dev !== directory.dev ||
      info.ino !== directory.ino
    ) {
      throw new Error(`Collector directory descriptor changed: ${directory.path}`);
    }
    if (process.platform === "darwin") {
      assertDarwinDirectoryBoundary(
        directory.path,
        await directory.handle.stat(),
      );
    }
  }
  const anchored = await anchor.handle.stat({ bigint: true });
  const current = await lstat(anchor.path, { bigint: true });
  if (
    current.isSymbolicLink() ||
    !current.isDirectory() ||
    anchored.dev !== anchor.dev ||
    anchored.ino !== anchor.ino ||
    current.dev !== anchor.dev ||
    current.ino !== anchor.ino
  ) {
    throw new Error(`Collector parent directory changed: ${anchor.path}`);
  }
}

async function openGenerationFile(
  anchor: ParentAnchor,
  name: string,
  resetOnStart: boolean,
): Promise<FileHandle> {
  await assertParentAnchor(anchor);
  const descriptorPath = await descriptorRelativePath(anchor, name);
  if (process.platform === "linux" && !descriptorPath) {
    throw new Error("Linux collector files require /proc/self/fd traversal");
  }
  const pathname = descriptorPath ?? resolve(anchor.path, name);
  if (process.platform === "linux" && resetOnStart) {
    let existing: FileHandle | undefined;
    try {
      existing = await open(
        pathname,
        constants.O_RDWR | constants.O_NOFOLLOW | constants.O_NONBLOCK,
      );
      await assertOwnedSingleLinkFile(existing, name);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    } finally {
      await existing?.close().catch(() => {});
    }
    if (existing) {
      await assertParentAnchor(anchor);
      await unlink(pathname);
    }
  }
  let handle: FileHandle;
  handle = await open(
    pathname,
    constants.O_RDWR |
      constants.O_NOFOLLOW |
      constants.O_NONBLOCK |
      constants.O_CREAT |
      (process.platform === "linux" && resetOnStart ? constants.O_EXCL : 0),
    0o600,
  );
  try {
    const info = await assertOwnedSingleLinkFile(handle, name);
    await assertParentAnchor(anchor);
    if (!descriptorPath) {
      const current = await lstat(resolve(anchor.path, name), { bigint: true });
      if (
        current.isSymbolicLink() ||
        !current.isFile() ||
        current.dev !== info.dev ||
        current.ino !== info.ino
      ) {
        throw new Error(
          `Collector target was not opened within its anchored directory: ${name}`,
        );
      }
      await assertParentAnchor(anchor);
    }
    return handle;
  } catch (error) {
    await handle.close();
    throw error;
  }
}

async function assertSafeFileHandle(
  handle: FileHandle,
  name: string,
): Promise<Awaited<ReturnType<FileHandle["stat"]>>> {
  const info = await assertOwnedSingleLinkFile(handle, name);
  if ((Number(info.mode) & 0o7777) !== 0o600) {
    throw new Error(`Collector target mode is not 0600: ${name}`);
  }
  return info;
}

async function assertOwnedSingleLinkFile(
  handle: FileHandle,
  name: string,
): Promise<Awaited<ReturnType<FileHandle["stat"]>>> {
  const info = await handle.stat({ bigint: true });
  const expectedOwner = process.geteuid?.();
  if (
    !info.isFile() ||
    info.nlink !== 1n ||
    (expectedOwner !== undefined && info.uid !== BigInt(expectedOwner))
  ) {
    throw new Error(`Collector target is not a private owned file: ${name}`);
  }
  return info;
}

async function writeAll(
  handle: FileHandle,
  contents: Buffer,
  position: number,
  name: string,
): Promise<void> {
  let offset = 0;
  while (offset < contents.length) {
    await assertSafeFileHandle(handle, name);
    const { bytesWritten } = await handle.write(
      contents,
      offset,
      contents.length - offset,
      position + offset,
    );
    if (
      !Number.isSafeInteger(bytesWritten) ||
      bytesWritten <= 0 ||
      bytesWritten > contents.length - offset
    ) {
      throw new Error(`Collector write made no forward progress: ${name}`);
    }
    offset += bytesWritten;
  }
}

async function replaceHandle(
  anchor: ParentAnchor,
  handle: FileHandle,
  contents: Buffer,
): Promise<void> {
  await assertParentAnchor(anchor);
  await assertSafeFileHandle(handle, "collector log");
  await handle.truncate(0);
  await assertSafeFileHandle(handle, "collector log");
  if (contents.length > 0) {
    await writeAll(handle, contents, 0, "collector log");
    await assertSafeFileHandle(handle, "collector log");
  }
  await handle.sync();
}

function normalizeJsonl(contents: Buffer, maxOutputBytes: number): Buffer {
  if (contents.length === 0) return contents;
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(contents);
  } catch {
    return Buffer.alloc(0);
  }
  const completeLines = text.endsWith("\n")
    ? text.slice(0, -1).split("\n")
    : text.split("\n").slice(0, -1);
  const validLines: Buffer[] = [];
  for (const line of completeLines) {
    try {
      JSON.parse(line);
      const encoded = Buffer.from(`${line}\n`, "utf8");
      if (encoded.length <= maxOutputBytes) validLines.push(encoded);
    } catch {}
  }
  const retained: Buffer[] = [];
  let retainedBytes = 0;
  for (let index = validLines.length - 1; index >= 0; index -= 1) {
    const line = validLines[index];
    if (retainedBytes + line.length > maxOutputBytes) break;
    retained.unshift(line);
    retainedBytes += line.length;
  }
  return Buffer.concat(retained);
}

async function readNormalizedTail(
  handle: FileHandle,
  maxOutputBytes: number,
): Promise<{ contents: Buffer; originalSize: number }> {
  await assertSafeFileHandle(handle, "collector log");
  const info = await handle.stat();
  if (info.size === 0) {
    return { contents: Buffer.alloc(0), originalSize: 0 };
  }
  const readLimit = maxOutputBytes * 2;
  const readSize = Math.min(info.size, readLimit);
  const start = info.size - readSize;
  const tail = Buffer.alloc(readSize);
  await handle.read(tail, 0, readSize, start);
  let candidate = tail;
  if (start > 0) {
    const firstNewline = tail.indexOf(0x0a);
    candidate =
      firstNewline === -1 ? Buffer.alloc(0) : tail.subarray(firstNewline + 1);
  }
  return {
    contents: normalizeJsonl(candidate, maxOutputBytes),
    originalSize: info.size,
  };
}

function boundedLine(
  report: Record<string, unknown>,
  receivedAt: string,
  maxOutputBytes: number,
): Buffer {
  const line = Buffer.from(
    `${JSON.stringify({ ...report, receivedAt })}\n`,
    "utf8",
  );
  if (line.length <= maxOutputBytes) return line;

  const fallback = Buffer.from(
    `${JSON.stringify({
      type: "truncated-report",
      receivedAt,
      originalBytes: line.length,
    })}\n`,
    "utf8",
  );
  if (fallback.length > maxOutputBytes) {
    throw new Error("maxOutputBytes cannot fit a truncation record");
  }
  return fallback;
}

type CollectorGeneration = {
  active?: FileHandle;
  activeReads: Set<{ cancel: () => void }>;
  anchor?: ParentAnchor;
  closePromise?: Promise<void>;
  closed: boolean;
  initialize: Promise<void>;
  outputPath: string;
  pendingWrites: Set<Promise<void>>;
  rotated?: FileHandle;
};

async function appendBounded(
  generation: CollectorGeneration,
  line: Buffer,
  maxOutputBytes: number,
): Promise<void> {
  await generation.initialize;
  if (
    !generation.active ||
    !generation.rotated ||
    !generation.anchor
  ) {
    throw new Error("Collector generation is closed");
  }
  const { contents: existing, originalSize } = await readNormalizedTail(
    generation.active,
    maxOutputBytes,
  );
  if (originalSize !== existing.length) {
    await replaceHandle(generation.anchor, generation.active, existing);
  }
  if (existing.length + line.length <= maxOutputBytes) {
    await assertParentAnchor(generation.anchor);
    await writeAll(
      generation.active,
      line,
      existing.length,
      "active collector log",
    );
    await generation.active.sync();
    return;
  }
  await replaceHandle(generation.anchor, generation.rotated, existing);
  await replaceHandle(generation.anchor, generation.active, line);
}

function reportIsWithinComplexityBounds(report: Record<string, unknown>): boolean {
  const stack: Array<{ depth: number; value: unknown }> = [
    { depth: 0, value: report },
  ];
  let keyCount = 0;
  while (stack.length > 0) {
    const { depth, value } = stack.pop()!;
    if (!value || typeof value !== "object") continue;
    if (depth > 32) return false;
    const keys = Object.keys(value);
    keyCount += keys.length;
    if (keyCount > 1_000) return false;
    for (const key of keys) {
      const nested = (value as Record<string, unknown>)[key];
      if (nested && typeof nested === "object") {
        stack.push({ depth: depth + 1, value: nested });
      }
    }
  }
  return true;
}

export function createErrorCollectorHooks(
  options: ErrorCollectorOptions = {},
): ErrorCollectorHooks {
  const endpoint = normalizeEndpoint(options.endpoint ?? DEFAULT_ENDPOINT);
  const outputFile = options.outputFile ?? DEFAULT_OUTPUT_FILE;
  const usesDefaultOutputFile = options.outputFile === undefined;
  const maxBodyBytes = options.maxBodyBytes ?? DEFAULT_MAX_BODY_BYTES;
  const maxOutputBytes = options.maxOutputBytes ?? DEFAULT_MAX_OUTPUT_BYTES;
  const bodyReadTimeoutMs =
    options.bodyReadTimeoutMs ?? DEFAULT_BODY_READ_TIMEOUT_MS;
  const resetOnStart = options.resetOnStart ?? true;
  validatePositiveSafeInteger(maxBodyBytes, "maxBodyBytes");
  validatePositiveSafeInteger(maxOutputBytes, "maxOutputBytes");
  if (maxOutputBytes < MIN_MAX_OUTPUT_BYTES) {
    throw new Error(
      `errorCollectorPlugin maxOutputBytes must be at least ${MIN_MAX_OUTPUT_BYTES}`,
    );
  }
  validatePositiveSafeInteger(bodyReadTimeoutMs, "bodyReadTimeoutMs");

  const clientScript = browserCollectorScript(endpoint);
  let outputPath = resolveCollectorOutput(process.cwd(), outputFile);
  const generationRecords: Array<{
    close: () => Promise<void>;
    httpServer?: HttpServer;
  }> = [];

  return {
    configResolved(config) {
      outputPath = resolveCollectorOutput(config.root, outputFile);
    },
    configureServer(server) {
      const generation: CollectorGeneration = {
        activeReads: new Set(),
        closed: false,
        initialize: Promise.resolve(),
        outputPath,
        pendingWrites: new Set(),
      };
      let detachHttpClose = () => {};
      const generationRecord = {} as (typeof generationRecords)[number];
      const closeHandles = async () => {
        const fileHandles = [
          generation.active,
          generation.rotated,
        ];
        const directoryChain = generation.anchor?.chain ?? [];
        generation.active = undefined;
        generation.rotated = undefined;
        generation.anchor = undefined;
        await Promise.all([
          ...fileHandles.map((handle) => handle?.close().catch(() => {})),
          ...directoryChain.map(({ handle }) => handle.close().catch(() => {})),
        ]);
      };
      const closeGeneration = (): Promise<void> => {
        if (generation.closePromise) return generation.closePromise;
        generation.closed = true;
        for (const read of [...generation.activeReads]) read.cancel();
        generation.closePromise = Promise.allSettled([
          generation.initialize,
          ...generation.pendingWrites,
        ])
          .then(closeHandles)
          .catch(() => {})
          .finally(() => {
            detachHttpClose();
            const recordIndex = generationRecords.indexOf(generationRecord);
            if (recordIndex !== -1) generationRecords.splice(recordIndex, 1);
          });
        return generation.closePromise;
      };
      generationRecord.close = closeGeneration;
      generationRecord.httpServer = server.httpServer ?? undefined;
      generationRecords.push(generationRecord);

      void Promise.resolve(
        server.watcher.unwatch(generation.outputPath),
      ).catch(() => {});
      void Promise.resolve(
        server.watcher.unwatch(`${generation.outputPath}.1`),
      ).catch(() => {});
      generation.initialize = queueForPath(generation.outputPath, async () => {
        const parentPath = dirname(generation.outputPath);
        let anchor: ParentAnchor | undefined;
        let active: FileHandle | undefined;
        let rotated: FileHandle | undefined;
        try {
          anchor = await createAndAnchorParent(
            parentPath,
            usesDefaultOutputFile &&
              parentPath ===
                dirname(resolveCollectorOutput("/", DEFAULT_OUTPUT_FILE)),
          );
          const outputName = basename(generation.outputPath);
          active = await openGenerationFile(
            anchor,
            outputName,
            resetOnStart,
          );
          rotated = await openGenerationFile(
            anchor,
            `${outputName}.1`,
            resetOnStart,
          );
          for (const [handle, name] of [
            [active, outputName],
            [rotated, `${outputName}.1`],
          ] as const) {
            await assertOwnedSingleLinkFile(handle, name);
          }
          for (const [handle, name] of [
            [active, outputName],
            [rotated, `${outputName}.1`],
          ] as const) {
            await assertOwnedSingleLinkFile(handle, name);
            await handle.chmod(0o600);
            await assertSafeFileHandle(handle, name);
          }
          if (resetOnStart) {
            await replaceHandle(anchor, active, Buffer.alloc(0));
            await replaceHandle(anchor, rotated, Buffer.alloc(0));
          } else {
            for (const handle of [active, rotated]) {
              const { contents, originalSize } = await readNormalizedTail(
                handle,
                maxOutputBytes,
              );
              if (originalSize !== contents.length) {
                await replaceHandle(anchor, handle, contents);
              }
            }
          }
          generation.anchor = anchor;
          generation.active = active;
          generation.rotated = rotated;
          anchor = undefined;
          active = undefined;
          rotated = undefined;
        } finally {
          await active?.close().catch(() => {});
          await rotated?.close().catch(() => {});
          await closeDirectoryChain(anchor?.chain ?? []);
        }
      });
      generation.initialize.catch(() => {});

      if (server.httpServer) {
        detachHttpClose = attachHttpServerClose(server.httpServer, () => {
          void closeGeneration();
        });
      }

      server.middlewares.use((request, response, next) => {
        if (
          request.method !== "POST" ||
          requestPathname(request) !== endpoint
        ) {
          return next();
        }
        if (generation.closed) {
          sendJson(response, 503, { error: "collector_closed" });
          return;
        }

        const read = readJsonBody(request, maxBodyBytes, bodyReadTimeoutMs);
        generation.activeReads.add(read);
        void read.promise
          .then(async (parsed) => {
            generation.activeReads.delete(read);
            if (
              (!parsed.ok && parsed.reason === "closed") ||
              response.destroyed
            ) {
              return;
            }
            if (!parsed.ok) {
              writeMalformedBodyResponse(response, request, parsed.reason);
              return;
            }
            if (
              !parsed.value ||
              typeof parsed.value !== "object" ||
              Array.isArray(parsed.value)
            ) {
              sendJson(response, 400, { error: "body_must_be_an_object" });
              return;
            }

            const report = parsed.value as Record<string, unknown>;
            if (!reportIsWithinComplexityBounds(report)) {
              sendJson(response, 400, { error: "report_too_complex" });
              return;
            }
            let line: Buffer;
            try {
              line = boundedLine(
                report,
                new Date().toISOString(),
                maxOutputBytes,
              );
            } catch {
              sendJson(response, 400, { error: "invalid_report" });
              return;
            }
            if (generation.closed) {
              sendJson(response, 503, { error: "collector_closed" });
              return;
            }
            const write = queueForPath(generation.outputPath, () =>
              appendBounded(generation, line, maxOutputBytes),
            );
            generation.pendingWrites.add(write);
            void write.then(
              () => generation.pendingWrites.delete(write),
              () => generation.pendingWrites.delete(write),
            );
            try {
              await write;
              response.writeHead(204);
              response.end();
            } catch (error) {
              server.config.logger.error(
                `Failed to write browser error to ${generation.outputPath}: ${String(error)}`,
              );
              sendJson(response, 500, { error: "write_failed" });
            }
          })
          .catch((error) => {
            generation.activeReads.delete(read);
            server.config.logger.error(
              `Failed to process browser error for ${generation.outputPath}: ${String(error)}`,
            );
            if (!response.destroyed && !response.writableEnded) {
              sendJson(response, 500, { error: "collector_failed" });
            }
          });
      });
      return closeGeneration;
    },
    transform(code, id, transformOptions) {
      if (transformOptions?.ssr || !isViteClientCarrier(id)) return null;
      if (code.includes(COLLECTOR_INSTALL_FLAG)) return { code, map: null };
      return {
        code: `${code}\n${clientScript}\n`,
        map: null,
      };
    },
    transformIndexHtml() {
      return [
        {
          tag: "script",
          children: clientScript,
          injectTo: "head-prepend",
        },
      ];
    },
    async close() {
      const detached = generationRecords.find(
        (generation) => !generation.httpServer,
      );
      await (detached?.close() ?? Promise.resolve());
    },
  };
}

export function errorCollectorPlugin(
  options: ErrorCollectorOptions = {},
): Plugin {
  const hooks = createErrorCollectorHooks(options);
  return {
    name: "vibe-error-collector",
    apply: "serve",
    configResolved(config) {
      hooks.configResolved(config);
    },
    configureServer(server) {
      hooks.configureServer(server);
    },
    transform(code, id, options) {
      return hooks.transform(code, id, options);
    },
    transformIndexHtml() {
      return hooks.transformIndexHtml();
    },
    closeWatcher() {},
    closeBundle() {
      return hooks.close();
    },
  };
}
