import type { ServerResponse } from "node:http";
import type { Plugin, ViteDevServer } from "vite";

import {
  attachHttpServerClose,
  createErrorCollectorHooks,
  errorCollectorPlugin,
  type ErrorCollectorOptions,
} from "./error-collector";
import {
  isViteClientCarrier,
  readJsonBody,
  requestPathname,
  sendJson,
  writeMalformedBodyResponse,
} from "./http";

export { errorCollectorPlugin };
export type { ErrorCollectorOptions };

const RESTART_ANNOUNCE_PATH = "/__vibe/restart-announce";
const PREVIEW_VIEWERS_PATH = "/_sandbox/preview/viewers";
const PREVIEW_EXECUTE_PATH = "/_sandbox/preview/execute";
const RESTART_EVENT = "vibe:dev-server-restarting";
const PREVIEW_EXECUTE_EVENT = "vibe:preview-execute";
const PREVIEW_EXECUTE_RESULT_EVENT = "vibe:preview-execute-result";
const CLIENT_MODULE_ID = "virtual:vibe-dev-server-bridge-client";
const RESOLVED_CLIENT_MODULE_ID = `\0${CLIENT_MODULE_ID}`;
const RESTART_MAX_BODY_BYTES = 1_024;
const PREVIEW_EXECUTE_MAX_BODY_BYTES = 64 * 1_024;
const PREVIEW_EXECUTE_MAX_CODE_LENGTH = 50 * 1_024;
const PREVIEW_EXECUTE_DEFAULT_TIMEOUT_MS = 1_500;
const PREVIEW_EXECUTE_MAX_TIMEOUT_MS = 5_000;
const CONTROL_BODY_READ_TIMEOUT_MS = 2_000;
const MAX_RESULT_VALUE_BYTES = 3 * 1_024;
const MAX_RESULT_BYTES = 4 * 1_024;
const MAX_EXECUTION_RESPONSE_BYTES = 256 * 1_024;
const MAX_RETURNED_RESULTS = 50;
const MAX_SANITIZER_NODES = 256;
const MAX_SANITIZER_PROPERTIES = 512;
const MAX_SANITIZER_STRING_BYTES = 8 * 1_024;
const MAX_SANITIZER_WORK = 4 * 1_024;
const MAX_PROPERTIES_PER_VALUE = 50;
let requestSequence = 0;

export interface DevServerBridgeOptions {
  /** Maximum time to wait for a complete control request body. */
  controlBodyReadTimeoutMs?: number;
  /** Browser error collector options, or false to disable it. */
  errorCollector?: false | ErrorCollectorOptions;
}

function nextRequestID(): string {
  requestSequence += 1;
  return `preview-exec-${Date.now().toString(36)}-${requestSequence.toString(36)}`;
}

function clampTimeoutMs(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return PREVIEW_EXECUTE_DEFAULT_TIMEOUT_MS;
  }
  return Math.max(
    1,
    Math.min(PREVIEW_EXECUTE_MAX_TIMEOUT_MS, Math.trunc(value)),
  );
}

type PreviewExecuteRequest = {
  code: string;
  timeoutMs: number;
};

function parsePreviewExecuteRequest(
  value: unknown,
): PreviewExecuteRequest | string {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return "body_must_be_an_object";
  }
  const code = "code" in value ? value.code : undefined;
  if (typeof code !== "string" || code.trim() === "") {
    return "code_must_be_a_non_empty_string";
  }
  if (Buffer.byteLength(code, "utf8") > PREVIEW_EXECUTE_MAX_CODE_LENGTH) {
    return "code_too_large";
  }
  return {
    code,
    timeoutMs: clampTimeoutMs("timeout_ms" in value ? value.timeout_ms : undefined),
  };
}

type PreviewExecuteResult = {
  request_id: string;
  viewer_id: string;
  ok: boolean;
  duration_ms: number;
  [key: string]: unknown;
};

type NormalizedPreviewExecuteResult = {
  request_id: string;
  viewer_id: string;
  ok: boolean;
  duration_ms: number;
  value?: unknown;
  error?: unknown;
};

function isPreviewExecuteResult(value: unknown): value is PreviewExecuteResult {
  if (!value || typeof value !== "object") return false;
  const result = value as Partial<PreviewExecuteResult>;
  return (
    typeof result.request_id === "string" &&
    typeof result.viewer_id === "string" &&
    typeof result.ok === "boolean" &&
    typeof result.duration_ms === "number" &&
    Number.isFinite(result.duration_ms)
  );
}

function clipUtf8(value: unknown, maxBytes: number): string {
  const text = String(value ?? "");
  if (Buffer.byteLength(text, "utf8") <= maxBytes) return text;
  let low = 0;
  let high = text.length;
  while (low < high) {
    const middle = Math.ceil((low + high) / 2);
    if (Buffer.byteLength(`${text.slice(0, middle)}…`, "utf8") <= maxBytes) {
      low = middle;
    } else {
      high = middle - 1;
    }
  }
  return `${text.slice(0, low)}…`;
}

function sanitizeResultValue(input: unknown): unknown {
  const workBudgetExceeded = () => ({
    type: "truncated",
    reason: "work_budget",
  });
  const holder: { value?: unknown } = {};
  const seen = new WeakSet<object>();
  let nodes = 0;
  let properties = 0;
  let stringBytes = 0;
  let work = 0;
  const boundedString = (value: unknown, perValueBytes: number): string => {
    const text = String(value ?? "");
    const allowedBytes = Math.max(
      0,
      Math.min(
        perValueBytes,
        MAX_SANITIZER_STRING_BYTES - stringBytes,
      ),
    );
    const chunks: string[] = [];
    let bytes = 0;
    let truncated = false;
    for (const character of text) {
      work += 1;
      if (work > MAX_SANITIZER_WORK) {
        truncated = true;
        break;
      }
      const characterBytes = Buffer.byteLength(character, "utf8");
      if (bytes + characterBytes > allowedBytes) {
        truncated = true;
        break;
      }
      chunks.push(character);
      bytes += characterBytes;
    }
    stringBytes += bytes;
    if (truncated && bytes + 3 <= allowedBytes) {
      chunks.push("…");
      stringBytes += 3;
    }
    return chunks.join("");
  };
  const tasks: Array<{
    depth: number;
    input: unknown;
    key: string | number;
    output: Record<string, unknown> | unknown[];
  }> = [{ depth: 0, input, key: "value", output: holder }];
  while (tasks.length > 0) {
    work += 1;
    nodes += 1;
    if (work > MAX_SANITIZER_WORK || nodes > MAX_SANITIZER_NODES) {
      return workBudgetExceeded();
    }
    const task = tasks.pop()!;
    let normalized: unknown;
    try {
      const value = task.input;
      if (value === null || typeof value === "boolean") normalized = value;
      else if (typeof value === "string") {
        normalized = boundedString(value, 2_048);
      }
      else if (typeof value === "number") {
        normalized = Number.isFinite(value) ? value : String(value);
      } else if (typeof value === "bigint") {
        normalized = { type: "bigint", value: String(value) };
      } else if (value === undefined) normalized = { type: "undefined" };
      else if (typeof value === "symbol" || typeof value === "function") {
        normalized = {
          type: typeof value,
          value: boundedString(value, 1_024),
        };
      } else if (value && typeof value === "object") {
        if (seen.has(value)) normalized = "[Circular]";
        else if (task.depth >= 6) normalized = "[MaxDepth]";
        else {
          seen.add(value);
          normalized = Array.isArray(value) ? [] : {};
          if (Array.isArray(value)) {
            if (
              value.length > MAX_PROPERTIES_PER_VALUE ||
              properties + value.length > MAX_SANITIZER_PROPERTIES ||
              nodes + tasks.length + value.length > MAX_SANITIZER_NODES
            ) {
              return workBudgetExceeded();
            }
            properties += value.length;
            for (let index = value.length - 1; index >= 0; index -= 1) {
              tasks.push({
                depth: task.depth + 1,
                input: value[index],
                key: index,
                output: normalized as unknown[],
              });
            }
          } else {
            let ownProperties = 0;
            for (const key in value) {
              work += 1;
              if (work > MAX_SANITIZER_WORK) return workBudgetExceeded();
              if (!Object.hasOwn(value, key)) continue;
              ownProperties += 1;
              properties += 1;
              if (
                ownProperties > MAX_PROPERTIES_PER_VALUE ||
                properties > MAX_SANITIZER_PROPERTIES ||
                nodes + tasks.length + ownProperties > MAX_SANITIZER_NODES
              ) {
                return workBudgetExceeded();
              }
              tasks.push({
                depth: task.depth + 1,
                input: (value as Record<string, unknown>)[key],
                key: boundedString(key, 256),
                output: normalized as Record<string, unknown>,
              });
            }
          }
        }
      } else normalized = boundedString(value, 1_024);
    } catch {
      normalized = "[Unserializable]";
    }
    task.output[task.key as never] = normalized as never;
  }
  const normalized = holder.value;
  const encoded = JSON.stringify(normalized);
  if (Buffer.byteLength(encoded, "utf8") <= MAX_RESULT_VALUE_BYTES) {
    return normalized;
  }
  return {
    type: "truncated",
    originalBytes: Buffer.byteLength(encoded, "utf8"),
    preview: clipUtf8(encoded, 2 * 1_024),
  };
}

function normalizePreviewExecuteResult(
  requestID: string,
  result: PreviewExecuteResult,
): NormalizedPreviewExecuteResult {
  const normalized: NormalizedPreviewExecuteResult = {
    request_id: requestID,
    viewer_id: clipUtf8(result.viewer_id, 256),
    ok: result.ok,
    duration_ms: Math.max(0, Math.min(300_000, result.duration_ms)),
  };
  if (result.ok) normalized.value = sanitizeResultValue(result.value);
  else normalized.error = sanitizeResultValue(result.error);
  const encoded = JSON.stringify(normalized);
  if (Buffer.byteLength(encoded, "utf8") > MAX_RESULT_BYTES) {
    if (result.ok) {
      normalized.value = { type: "truncated", originalBytes: encoded.length };
    } else {
      normalized.error = { type: "truncated", originalBytes: encoded.length };
    }
  }
  return normalized;
}

function sendExecutionResponse(
  response: ServerResponse,
  requestID: string,
  viewerCount: number,
  results: Map<unknown, NormalizedPreviewExecuteResult>,
): void {
  const returnedResults = [...results.values()].slice(0, MAX_RETURNED_RESULTS);
  const omittedResultCount = results.size - returnedResults.length;
  const body: Record<string, unknown> = {
    request_id: requestID,
    viewer_count: viewerCount,
    responded_count: results.size,
    timed_out_count: Math.max(0, viewerCount - results.size),
    results: returnedResults,
    ...(omittedResultCount > 0
      ? { omitted_result_count: omittedResultCount }
      : {}),
  };
  let encoded = JSON.stringify(body);
  if (Buffer.byteLength(encoded, "utf8") > MAX_EXECUTION_RESPONSE_BYTES) {
    body.results = [];
    body.omitted_result_count = results.size;
    encoded = JSON.stringify(body);
  }
  response.writeHead(200, {
    "Content-Type": "application/json; charset=utf-8",
  });
  response.end(encoded);
}

function browserClientScript(): string {
  return `
if (import.meta.hot) {
  const hot = import.meta.hot;
  const hotContexts =
    globalThis.__vibeDevServerBridgeHotContexts ||
    (globalThis.__vibeDevServerBridgeHotContexts = new WeakSet());
  if (!hotContexts.has(hot)) {
  hotContexts.add(hot);
  const viewerID =
    globalThis.__vibePreviewExecuteViewerID ||
    (globalThis.__vibePreviewExecuteViewerID =
      globalThis.crypto?.randomUUID?.() ?? Math.random().toString(36).slice(2));
  const handled =
    globalThis.__vibePreviewExecuteHandled ||
    (globalThis.__vibePreviewExecuteHandled = new Set());
  const restartPayloads =
    globalThis.__vibeRestartPayloads ||
    (globalThis.__vibeRestartPayloads = new WeakSet());
  const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
  const now = () => globalThis.performance?.now?.() ?? Date.now();
  const encoder = new (globalThis.TextEncoder || TextEncoder)();
  const utf8Length = (value) => encoder.encode(value).length;
  const clipString = (value, maxBytes = 4096) => {
    const text = String(value ?? "");
    if (utf8Length(text) <= maxBytes) return text;
    let low = 0;
    let high = text.length;
    while (low < high) {
      const middle = Math.ceil((low + high) / 2);
      if (utf8Length(text.slice(0, middle) + "…") <= maxBytes) low = middle;
      else high = middle - 1;
    }
    return text.slice(0, low) + "…";
  };
  const normalize = (value, seen = new WeakSet(), depth = 0) => {
    if (value === null || typeof value === "boolean") return value;
    if (typeof value === "string") return clipString(value);
    if (typeof value === "number") {
      return Number.isFinite(value) ? value : String(value);
    }
    if (typeof value === "bigint") {
      return { type: "bigint", value: String(value) };
    }
    if (value === undefined) return { type: "undefined" };
    if (typeof value === "symbol") {
      return { type: "symbol", value: clipString(value, 2048) };
    }
    if (typeof value === "function") {
      return { type: "function", value: clipString(value, 2048) };
    }
    if (value instanceof Error) {
      return {
        type: "error",
        name: clipString(value.name, 1024),
        message: clipString(value.message),
        stack: value.stack ? clipString(value.stack) : undefined,
      };
    }
    if (!value || typeof value !== "object") return clipString(value);
    if (seen.has(value)) return "[Circular]";
    if (depth >= 6) return "[MaxDepth]";
    seen.add(value);
    if (Array.isArray(value)) {
      return value.slice(0, 50).map((entry) =>
        normalize(entry, seen, depth + 1)
      );
    }
    const normalized = {};
    for (const key of Object.keys(value).slice(0, 50)) {
      try {
        normalized[clipString(key, 512)] = normalize(
          value[key],
          seen,
          depth + 1,
        );
      } catch {
        normalized[clipString(key, 512)] = "[Unserializable]";
      }
    }
    return normalized;
  };
  const serialize = (value) => {
    try {
      const normalized = normalize(value);
      const json = JSON.stringify(normalized);
      if (utf8Length(json) <= 12 * 1024) return normalized;
      return {
        type: "truncated",
        originalBytes: utf8Length(json),
        preview: clipString(json, 10 * 1024),
      };
    } catch {
      return { type: "unserializable", value: clipString(value, 2048) };
    }
  };

  hot.on("${RESTART_EVENT}", (payload) => {
    if (payload && typeof payload === "object") {
      if (restartPayloads.has(payload)) return;
      restartPayloads.add(payload);
    }
    const reason =
      payload && typeof payload.reason === "string" ? payload.reason : undefined;
    try {
      globalThis.parent?.postMessage(
        {
          type: "VIBE_DEV_SERVER_RESTARTING",
          ...(reason ? { reason } : {}),
        },
        "*",
      );
    } catch {}
  });

  hot.on("${PREVIEW_EXECUTE_EVENT}", async (payload) => {
    const requestID =
      payload && typeof payload.request_id === "string" ? payload.request_id : "";
    const code = payload && typeof payload.code === "string" ? payload.code : "";
    if (!requestID || !code || handled.has(requestID)) return;
    if (handled.size >= 10000) handled.clear();
    handled.add(requestID);
    const started = now();
    try {
      const value = await new AsyncFunction(code)();
      hot.send("${PREVIEW_EXECUTE_RESULT_EVENT}", {
        request_id: requestID,
        viewer_id: viewerID,
        ok: true,
        value: serialize(value),
        duration_ms: Math.round(now() - started),
      });
    } catch (error) {
      hot.send("${PREVIEW_EXECUTE_RESULT_EVENT}", {
        request_id: requestID,
        viewer_id: viewerID,
        ok: false,
        error: serialize(
          error instanceof Error
            ? error
            : new Error(clipString(error)),
        ),
        duration_ms: Math.round(now() - started),
      });
    }
  });
  }
}
`;
}

export function devServerBridgePlugin(
  options: DevServerBridgeOptions = {},
): Plugin {
  const controlBodyReadTimeoutMs =
    options.controlBodyReadTimeoutMs ?? CONTROL_BODY_READ_TIMEOUT_MS;
  if (
    !Number.isSafeInteger(controlBodyReadTimeoutMs) ||
    controlBodyReadTimeoutMs <= 0
  ) {
    throw new Error(
      "devServerBridgePlugin controlBodyReadTimeoutMs must be a positive safe integer",
    );
  }
  const errorCollector =
    options.errorCollector === false
      ? undefined
      : createErrorCollectorHooks(options.errorCollector);
  const generations: Array<{
    close: () => Promise<void>;
    httpServer?: NonNullable<ViteDevServer["httpServer"]>;
  }> = [];
  let emptyClosePromise: Promise<void> | undefined;
  const closeOldestDetached = (): Promise<void> => {
    const detached = generations.find((generation) => !generation.httpServer);
    if (detached) return detached.close();
    return (emptyClosePromise ??= Promise.resolve());
  };
  const injectHtmlClient = () => {
    const tags = errorCollector?.transformIndexHtml() ?? [];
    tags.push({
      tag: "script",
      attrs: { type: "module" },
      children: `import ${JSON.stringify(CLIENT_MODULE_ID)};`,
      injectTo: "head-prepend" as const,
    } as (typeof tags)[number]);
    return tags;
  };

  return {
    name: "vibe-dev-server-bridge",
    apply: "serve",
    configResolved(config) {
      errorCollector?.configResolved(config);
    },
    configureServer(server) {
      const closeCollector =
        errorCollector?.configureServer(server) ?? (() => Promise.resolve());
      const pendingRequests = new Set<{ cancel: () => void }>();
      const activeControlReads = new Set<{ cancel: () => void }>();
      let connectionSequence = 0;
      const ws = server.ws as typeof server.ws & {
        clients?: Iterable<unknown> & { size?: number };
        on?: (event: string, listener: (...args: unknown[]) => void) => void;
        off?: (event: string, listener: (...args: unknown[]) => void) => void;
      };
      const onConnection = () => {
        connectionSequence += 1;
      };
      ws.on?.("connection", onConnection);
      const executions = new Map<
        string,
        {
          addResult: (key: unknown, result: PreviewExecuteResult) => void;
          cancel: () => void;
        }
      >();
      const onExecuteResult = (data: unknown, client: unknown) => {
        if (!isPreviewExecuteResult(data)) return;
        executions
          .get(data.request_id)
          ?.addResult(client ?? data.viewer_id, data);
      };
      ws.on?.(PREVIEW_EXECUTE_RESULT_EVENT, onExecuteResult);
      let detachHttpClose = () => {};
      let closePromise: Promise<void> | undefined;
      const generation = {} as (typeof generations)[number];
      const closeGeneration = (): Promise<void> => {
        if (closePromise) return closePromise;
        for (const read of [...activeControlReads]) read.cancel();
        for (const execution of [...executions.values()]) execution.cancel();
        for (const pending of [...pendingRequests]) pending.cancel();
        ws.off?.("connection", onConnection);
        ws.off?.(PREVIEW_EXECUTE_RESULT_EVENT, onExecuteResult);
        closePromise = closeCollector().finally(() => {
          detachHttpClose();
          const index = generations.indexOf(generation);
          if (index !== -1) generations.splice(index, 1);
        });
        return closePromise;
      };
      generation.close = closeGeneration;
      generation.httpServer = server.httpServer ?? undefined;
      generations.push(generation);
      if (server.httpServer) {
        detachHttpClose = attachHttpServerClose(server.httpServer, () => {
          void closeGeneration();
        });
      }

      server.middlewares.use((request, response, next) => {
        const pathname = requestPathname(request);
        const isRestart =
          request.method === "POST" && pathname === RESTART_ANNOUNCE_PATH;
        const isViewers =
          request.method === "GET" && pathname === PREVIEW_VIEWERS_PATH;
        const isExecute =
          request.method === "POST" && pathname === PREVIEW_EXECUTE_PATH;
        if (!isRestart && !isViewers && !isExecute) return next();

        if (isViewers) {
          sendJson(response, 200, {
            viewer_count: ws.clients?.size ?? 0,
            connection_seq: connectionSequence,
          });
          return;
        }

        const maxBodyBytes = isExecute
          ? PREVIEW_EXECUTE_MAX_BODY_BYTES
          : RESTART_MAX_BODY_BYTES;
        const read = readJsonBody(
          request,
          maxBodyBytes,
          controlBodyReadTimeoutMs,
        );
        activeControlReads.add(read);
        void read.promise.then((parsed) => {
          activeControlReads.delete(read);
          if ((!parsed.ok && parsed.reason === "closed") || response.destroyed) {
            return;
          }
          if (!parsed.ok) {
            writeMalformedBodyResponse(response, request, parsed.reason);
            return;
          }
          if (
            !parsed.value ||
            typeof parsed.value !== "object" ||
            Array.isArray(parsed.value)
          ) {
            sendJson(response, 400, { error: "body_must_be_an_object" });
            return;
          }

          if (isExecute) {
            const previewRequest = parsePreviewExecuteRequest(parsed.value);
            if (typeof previewRequest === "string") {
              sendJson(response, 400, { error: previewRequest });
              return;
            }
            const requestID = nextRequestID();
            const expectedClients = new Set<unknown>(
              ws.clients ? [...ws.clients] : [],
            );
            const viewerCount = expectedClients.size;
            if (viewerCount === 0) {
              sendJson(response, 200, {
                request_id: requestID,
                viewer_count: 0,
                responded_count: 0,
                timed_out_count: 0,
                results: [],
              });
              return;
            }

            const results = new Map<unknown, NormalizedPreviewExecuteResult>();
            let completed = false;
            let timeout: NodeJS.Timeout;
            const finish = (cancelled = false) => {
              if (completed) return;
              completed = true;
              clearTimeout(timeout);
              executions.delete(requestID);
              pendingRequests.delete(pending);
              if (cancelled) {
                sendJson(response, 503, { error: "bridge_closed" });
                return;
              }
              sendExecutionResponse(response, requestID, viewerCount, results);
            };
            const pending = { cancel: () => finish(true) };
            const execution = {
              addResult(key: unknown, result: PreviewExecuteResult) {
                if (
                  completed ||
                  !expectedClients.has(key) ||
                  results.has(key)
                ) {
                  return;
                }
                results.set(
                  key,
                  normalizePreviewExecuteResult(requestID, result),
                );
                if (results.size >= viewerCount) finish();
              },
              cancel: pending.cancel,
            };
            executions.set(requestID, execution);
            pendingRequests.add(pending);
            timeout = setTimeout(finish, previewRequest.timeoutMs);
            server.ws.send({
              type: "custom",
              event: PREVIEW_EXECUTE_EVENT,
              data: {
                request_id: requestID,
                code: previewRequest.code,
              },
            });
            return;
          }

          if (
            "reason" in parsed.value &&
            typeof parsed.value.reason !== "string"
          ) {
            sendJson(response, 400, { error: "reason_must_be_a_string" });
            return;
          }
          const reason =
            "reason" in parsed.value ? parsed.value.reason : undefined;
          server.ws.send({
            type: "custom",
            event: RESTART_EVENT,
            data: reason ? { reason } : {},
          });
          response.writeHead(204);
          response.end();
        });
      });
    },
    closeWatcher() {},
    closeBundle() {
      return closeOldestDetached();
    },
    resolveId(id) {
      if (id === CLIENT_MODULE_ID) return RESOLVED_CLIENT_MODULE_ID;
      return null;
    },
    load(id) {
      if (id === RESOLVED_CLIENT_MODULE_ID) return browserClientScript();
      return null;
    },
    transform(code, id, transformOptions) {
      const collectorTransform = errorCollector?.transform(
        code,
        id,
        transformOptions,
      );
      if (transformOptions?.ssr || !isViteClientCarrier(id)) {
        return collectorTransform ?? null;
      }
      const transformedCode = collectorTransform?.code ?? code;
      if (transformedCode.includes(CLIENT_MODULE_ID)) {
        return { code: transformedCode, map: null };
      }
      return {
        code: `${transformedCode}\nimport(${JSON.stringify(CLIENT_MODULE_ID)});\n`,
        map: null,
      };
    },
    transformIndexHtml: { order: "pre", handler: injectHtmlClient },
  };
}
