import type { IncomingMessage, ServerResponse } from "node:http";

export type JsonBodyResult =
  | { ok: true; value: unknown }
  | {
      ok: false;
      reason:
        | "body_timeout"
        | "closed"
        | "empty"
        | "invalid_json"
        | "read_error"
        | "too_large";
    };

type JsonBodyFailure = Extract<JsonBodyResult, { ok: false }>["reason"];

export function requestPathname(request: IncomingMessage): string {
  const url = request.url ?? "";
  const queryIndex = url.indexOf("?");
  return queryIndex === -1 ? url : url.slice(0, queryIndex);
}

export function sendJson(
  response: ServerResponse,
  status: number,
  body: Record<string, unknown>,
): void {
  response.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
  });
  response.end(JSON.stringify(body));
}

export function readJsonBody(
  request: IncomingMessage,
  maxBodyBytes: number,
  timeoutMs: number,
): { cancel: () => void; promise: Promise<JsonBodyResult> } {
  let cancel = () => {};
  const promise = new Promise<JsonBodyResult>((resolveBody) => {
    const chunks: Buffer[] = [];
    let receivedBytes = 0;
    let settled = false;
    const cleanup = () => {
      clearTimeout(timeout);
      request.off("data", onData);
      request.off("end", onEnd);
      request.off("error", onError);
      request.off("aborted", onAborted);
    };
    const settle = (result: JsonBodyResult) => {
      if (settled) return;
      settled = true;
      cleanup();
      resolveBody(result);
    };
    const onData = (chunk: Buffer | string) => {
      if (settled) return;
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      receivedBytes += buffer.length;
      if (receivedBytes > maxBodyBytes) {
        settle({ ok: false, reason: "too_large" });
        return;
      }
      chunks.push(buffer);
    };
    const onEnd = () => {
      if (settled) return;
      if (chunks.length === 0) {
        settle({ ok: false, reason: "empty" });
        return;
      }
      try {
        settle({
          ok: true,
          value: JSON.parse(Buffer.concat(chunks).toString("utf8")),
        });
      } catch {
        settle({ ok: false, reason: "invalid_json" });
      }
    };
    const onError = () => settle({ ok: false, reason: "read_error" });
    const onAborted = () => settle({ ok: false, reason: "read_error" });
    const timeout = setTimeout(
      () => settle({ ok: false, reason: "body_timeout" }),
      timeoutMs,
    );
    timeout.unref?.();
    request.on("data", onData);
    request.on("end", onEnd);
    request.on("error", onError);
    request.on("aborted", onAborted);
    cancel = () => {
      settle({ ok: false, reason: "closed" });
      request.destroy();
    };
  });
  return { cancel, promise };
}

/**
 * Emit the 413/408/400 rejection for a malformed control/report body and,
 * for the resource-exhaustion cases, tear the socket down after the response
 * flushes. Shared by every JSON endpoint so the protocol contract lives once.
 */
export function writeMalformedBodyResponse(
  response: ServerResponse,
  request: IncomingMessage,
  reason: JsonBodyFailure,
): void {
  const status =
    reason === "too_large" ? 413 : reason === "body_timeout" ? 408 : 400;
  response.writeHead(status, {
    "Connection": "close",
    "Content-Type": "application/json; charset=utf-8",
  });
  response.end(JSON.stringify({ error: reason }));
  if (reason === "body_timeout" || reason === "too_large") {
    response.once("finish", () => request.destroy());
  }
}

export function isViteClientCarrier(id: string): boolean {
  return /\/node_modules\/vite[^/]*\/dist\/client\/client\.mjs(?:$|\?)/.test(
    id.replaceAll("\\", "/"),
  );
}
